import re
import numpy as np

# The sandbox has no network, so embed() stands in for client.embeddings.create(...).
# Like a real embedding model it returns a unit-length vector, and texts about the
# same topic point in similar directions.
TOPIC_WORDS = {
    0: {"ai", "artificial", "intelligence", "ml", "machine", "learning", "deep", "neural", "network", "model", "train"},
    1: {"restaurants", "restaurant", "food", "chennai", "dinner", "eat", "best"},
    2: {"cricket", "cup", "world", "schedule", "match", "sports"},
    3: {"tutorial", "tutorials", "introduction", "how", "guide", "learn"},
}


def embed(text):
    vec = np.full(5, 0.05)
    for word in re.findall(r"[a-z0-9]+", text.lower()):
        for dim, words in TOPIC_WORDS.items():
            if word in words:
                vec[dim] += 1.0
                break
        else:
            vec[4] += 0.2
    return vec / np.linalg.norm(vec)


def cosine_similarity(a, b):
    return float(np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b)))


def semantic_search(sentences, query, top_k=3):
    """Return the top_k (score, sentence) pairs, highest score first."""
    q = embed(query)
    scored = [(cosine_similarity(q, embed(s)), s) for s in sentences]
    scored.sort(key=lambda pair: pair[0], reverse=True)
    return scored[:top_k]


sentences = [
    "How to train a machine learning model",
    "Best restaurants in Chennai",
    "Deep learning neural network tutorial",
    "Cricket World Cup 2026 schedule",
    "Introduction to artificial intelligence",
]
results = semantic_search(sentences, "AI and ML tutorials", top_k=3)
if results is None:
    print("semantic_search() returned None")
else:
    for score, text in results:
        print(f"{score:.4f}: {text}")
